<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Contact extends MY_Controller { public function index(){ if($this->input->method()==='post'){ $this->form_validation->set_rules('email','Email','required|valid_email');$this->form_validation->set_rules('message','Message','required|trim');if($this->form_validation->run()){$this->db->insert('contact_messages',array('name'=>$this->input->post('name',true),'email'=>$this->input->post('email',true),'message'=>$this->input->post('message',true)));$this->session->set_flashdata('success','Thanks! Your message has been received.');redirect('contact');}}$this->view('contact/index');}}
